export class AppError extends Error {
  constructor(
    message: string,
    readonly field?: string,
  ) {
    super(message);
  }
}
export type ActionResult = {
  ok: boolean;
  message: string;
  id?: string;
  code?: string;
  allowance?: "DAILY" | "MONTHLY";
  remaining?: number;
  resetAt?: string;
  retryAfter?: number;
  fieldErrors?: Record<string, string>;
};

export function actionErrorDetails(error: AppError): Partial<ActionResult> {
  const value = error as AppError & {
    retryAfter?: number;
    code?: string;
    allowance?: "DAILY" | "MONTHLY";
    remaining?: number;
    resetAt?: Date;
  };
  return {
    ...(value.retryAfter ? { retryAfter: value.retryAfter } : {}),
    ...(value.code ? { code: value.code } : {}),
    ...(value.allowance
      ? {
          allowance: value.allowance,
          remaining: value.remaining,
          resetAt: value.resetAt?.toISOString(),
        }
      : {}),
  };
}
